#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using ld = long double;
using ull = unsigned long long;

const int dr[4] = {1, -1, 0, 0};
const int dc[4] = {0, 0, 1, -1};

int N, T, rStart, cStart;
string gridL[20], gridS[20];
int memo[12][12][12][12][62];
int cap[250][250], par[250];
int dist[20][20], vis[20][20];

bool valid(int r, int c) {
    return r >= 0 && r < N && c >= 0 && c < N && gridL[r][c] != 'Y' && gridL[r][c] != 'Z';
}

void bfsDist() {
    memset(dist, 0x3f, sizeof(dist));
    memset(vis, 0, sizeof(vis));
    dist[rStart][cStart] = 0;
    vis[rStart][cStart] = 1;
    queue<int> qr, qc;
    qr.push(rStart); qc.push(cStart);
    while (!qr.empty()) {
        int r = qr.front(); qr.pop();
        int c = qc.front(); qc.pop();
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (valid(nr, nc) && !vis[nr][nc]) {
                dist[nr][nc] = dist[r][c] + 1;
                vis[nr][nc] = 1;
                qr.push(nr); qc.push(nc);
            }
        }
    }
}

bool dfsPath(int r1, int c1, int r2, int c2, int step) {
    if (step > T) return false;
    int& res = memo[r1][c1][r2][c2][step];
    if (res != -1) return res;
    if (r1 == r2 && c1 == c2) return res = (dist[r1][c1] >= step);
    if (dist[r1][c1] <= step) return res = false;
    for (int k = 0; k < 4; ++k) {
        int nr = r1 + dr[k];
        int nc = c1 + dc[k];
        if (valid(nr, nc) && dfsPath(nr, nc, r2, c2, step + 1)) return res = true;
    }
    return res = false;
}

bool bfsFlow(int s, int t) {
    memset(par, -1, sizeof(par));
    par[s] = -2;
    queue<int> q;
    q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v = s; v <= t; ++v) {
            if (par[v] == -1 && cap[u][v] > 0) {
                par[v] = u;
                q.push(v);
            }
        }
    }
    return par[t] != -1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(32);

    cin >> N >> T;
    for (int i = 0; i < N; ++i) cin >> gridS[i];
    for (int i = 0; i < N; ++i) cin >> gridL[i];

    vector<pair<int, int>> points;
    vector<int> labC, sciC;
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (gridS[i][j] == 'Z') {
                rStart = i; cStart = j;
            } else if (isdigit(gridS[i][j])) {
                points.emplace_back(i, j);
                labC.push_back(gridL[i][j] - '0');
                sciC.push_back(gridS[i][j] - '0');
            }
        }
    }

    int m = points.size();
    memset(cap, 0, sizeof(cap));
    for (int i = 0; i < m; ++i) {
        cap[0][i + 1] = sciC[i];
        cap[m + 1 + i][2 * m + 1] = labC[i];
    }

    bfsDist();
    memset(memo, -1, sizeof(memo));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < m; ++j) {
            if (dfsPath(points[i].first, points[i].second, points[j].first, points[j].second, 0)) {
                cap[i + 1][m + 1 + j] = 1000;
            }
        }
    }

    int maxFlow = 0;
    while (bfsFlow(0, 2 * m + 1)) {
        int sink = 2 * m + 1;
        int flow = 1000000;
        while (par[sink] >= 0) {
            flow = min(flow, cap[par[sink]][sink]);
            sink = par[sink];
        }
        sink = 2 * m + 1;
        while (par[sink] >= 0) {
            cap[par[sink]][sink] -= flow;
            cap[sink][par[sink]] += flow;
            sink = par[sink];
        }
        maxFlow += flow;
    }

    cout << maxFlow;
    return 0;
}
